//! Private unified Scheme runtime.
//!
//! The hot Scheme graph is owned by one tracing heap and contains only compact handles;
//! Rust ownership is retained at the immutable-module and explicit host-root boundaries,
//! not on individual Scheme edges. Request-local values, continuations, side tables, and
//! dynamic literals are reset as one generation. See `docs/unified-runtime-readiness.md`.

use std::cell::{Cell, RefCell};
use std::collections::{HashMap, HashSet};
use std::ffi::c_void;
use std::fmt;
use std::hash::Hash;
use std::ops::{Deref, DerefMut};
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::rc::{Rc, Weak};
use std::sync::Arc;

use sha2::{Digest, Sha256};

use crate::host::{BorrowedValue, HostArgument, HostCallContext, HostError, HostObject, HostOutput, PrimitiveSpec};
use crate::Value;

const TAG_BITS: u32 = 3;
const TAG_MASK: u64 = (1 << TAG_BITS) - 1;
const TAG_HEAP: u64 = 0;
const TAG_FIXNUM: u64 = 1;
const TAG_CHARACTER: u64 = 2;
const TAG_SPECIAL: u64 = 3;
const INDEX_BITS: u32 = 32;
const INDEX_MASK: u64 = u32::MAX as u64;
const EPOCH_BITS: u32 = 64 - TAG_BITS - INDEX_BITS;
const EPOCH_MASK: u32 = (1 << EPOCH_BITS) - 1;
const PAGE_CELLS: usize = 1024;
const UNIFIED_SEMANTIC_ABI: u64 = 1;

/// Shared identity-aware traversal used by both frozen source graphs and request-local
/// GC graphs. Nodes without identity can contain graph nodes but cannot close a cycle.
fn graph_has_cycle_by<Node: Clone, Identity: Copy + Eq + Hash>(
    root: Node,
    identity: impl Fn(&Node) -> Option<Identity>,
    children: impl Fn(&Node) -> Vec<Node>,
) -> bool {
    enum Visit<Node, Identity> { Enter(Node), Exit(Identity) }
    let mut active = HashSet::new();
    let mut done = HashSet::new();
    let mut stack = vec![Visit::Enter(root)];
    while let Some(visit) = stack.pop() {
        match visit {
            Visit::Exit(id) => { active.remove(&id); done.insert(id); }
            Visit::Enter(node) => {
                if let Some(id) = identity(&node) {
                    if active.contains(&id) { return true; }
                    if done.contains(&id) { continue; }
                    active.insert(id);
                    stack.push(Visit::Exit(id));
                }
                let mut next = children(&node);
                next.reverse();
                stack.extend(next.into_iter().map(Visit::Enter));
            }
        }
    }
    false
}

fn graph_reaches_identity_by<Node: Clone, Identity: Copy + Eq + Hash>(
    roots: impl IntoIterator<Item = Node>,
    target: Identity,
    identity: impl Fn(&Node) -> Option<Identity>,
    children: impl Fn(&Node) -> Vec<Node>,
) -> bool {
    let mut pending = roots.into_iter().collect::<Vec<_>>();
    let mut visited = HashSet::new();
    while let Some(node) = pending.pop() {
        if identity(&node) == Some(target) { return true; }
        if identity(&node).is_none_or(|id| visited.insert(id)) {
            pending.extend(children(&node));
        }
    }
    false
}

/// One copyable Scheme reference. Heap references contain an index and stale-handle epoch.
#[repr(transparent)]
#[derive(Clone, Copy, PartialEq, Eq, Hash)]
pub(crate) struct GcValue(u64);

impl GcValue {
    pub(crate) const FALSE: Self = Self((0 << TAG_BITS) | TAG_SPECIAL);
    pub(crate) const TRUE: Self = Self((1 << TAG_BITS) | TAG_SPECIAL);
    pub(crate) const NIL: Self = Self((2 << TAG_BITS) | TAG_SPECIAL);
    pub(crate) const UNSPECIFIED: Self = Self((3 << TAG_BITS) | TAG_SPECIAL);
    pub(crate) const UNDEFINED: Self = Self((4 << TAG_BITS) | TAG_SPECIAL);
    pub(crate) const EOF: Self = Self((5 << TAG_BITS) | TAG_SPECIAL);
    const UNINITIALIZED: Self = Self((6 << TAG_BITS) | TAG_SPECIAL);

    pub(crate) fn fixnum(value: i64) -> Option<Self> {
        const MIN: i64 = -(1_i64 << 60);
        const MAX: i64 = (1_i64 << 60) - 1;
        (MIN..=MAX)
            .contains(&value)
            .then(|| Self(((value as u64) << TAG_BITS) | TAG_FIXNUM))
    }

    pub(crate) fn as_fixnum(self) -> Option<i64> {
        (self.0 & TAG_MASK == TAG_FIXNUM).then(|| (self.0 as i64) >> TAG_BITS)
    }

    pub(crate) fn character(value: char) -> Self {
        Self(((value as u32 as u64) << TAG_BITS) | TAG_CHARACTER)
    }

    pub(crate) fn as_character(self) -> Option<char> {
        if self.0 & TAG_MASK != TAG_CHARACTER {
            return None;
        }
        char::from_u32((self.0 >> TAG_BITS) as u32)
    }

    fn heap(index: u32, epoch: u32) -> Self {
        debug_assert!(epoch > 0 && epoch <= EPOCH_MASK);
        Self(((epoch as u64) << (INDEX_BITS + TAG_BITS)) | ((index as u64) << TAG_BITS) | TAG_HEAP)
    }

    fn heap_parts(self) -> Option<(u32, u32)> {
        if self.0 & TAG_MASK != TAG_HEAP {
            return None;
        }
        let index = ((self.0 >> TAG_BITS) & INDEX_MASK) as u32;
        let epoch = (self.0 >> (INDEX_BITS + TAG_BITS)) as u32;
        (epoch != 0).then_some((index, epoch))
    }

    pub(crate) fn is_heap(self) -> bool {
        self.heap_parts().is_some()
    }
}

impl fmt::Debug for GcValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(value) = self.as_fixnum() {
            return write!(f, "{value}");
        }
        if let Some((index, epoch)) = self.heap_parts() {
            return write!(f, "#<gc:{index}:{epoch}>");
        }
        write!(f, "#<immediate:{:#x}>", self.0)
    }
}

/// Stable identifiers are used in environments and immutable modules. Symbol text is kept
/// in the engine interner, not duplicated in every binding.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub(crate) struct SymbolId(pub(crate) u32);

/// Every mutable Scheme graph node lives here. Children are compact `GcValue`s, never `Rc`s.
#[derive(Clone, Debug)]
pub(crate) struct EnvironmentData {
    parent: Option<GcValue>,
    bindings: HashMap<Arc<str>, GcValue>,
    order: Vec<Arc<str>>,
    history: Vec<(Arc<str>, GcValue)>,
}
#[derive(Clone, Debug, Default)]
pub(crate) struct HashTableData {
    entries: Vec<(GcValue, GcValue)>,
    equivalence: Option<GcValue>,
    key_checker: Option<GcValue>,
    value_checker: Option<GcValue>,
    key_checker_name: Option<Arc<str>>,
    value_checker_name: Option<Arc<str>>,
}

impl Deref for HashTableData {
    type Target = Vec<(GcValue, GcValue)>;

    fn deref(&self) -> &Self::Target {
        &self.entries
    }
}

impl DerefMut for HashTableData {
    fn deref_mut(&mut self) -> &mut Self::Target {
        &mut self.entries
    }
}

#[derive(Clone, Debug)]
pub(crate) struct LexicalFrameData {
    parent: Option<GcValue>,
    slots: Vec<GcValue>,
    names: Arc<[Option<Arc<str>>]>,
    dynamic: HashMap<Arc<str>, GcValue>,
    binding_setters: HashMap<u16, GcValue>,
}

#[derive(Clone, Debug)]
pub(crate) enum GcObject {
    Pair {
        car: GcValue,
        cdr: GcValue,
    },
    Vector(Vec<GcValue>),
    MultiVector {
        dims: Vec<usize>,
        values: Vec<GcValue>,
        kind: Option<char>,
    },
    MultiVectorView {
        base: GcValue,
        offset: usize,
        dims: Vec<usize>,
        kind: Option<char>,
    },
    ByteVector(Vec<u8>),
    FloatVector(Vec<f64>),
    IntVector(Vec<i64>),
    HashTable(Box<HashTableData>),
    Values(Box<Vec<GcValue>>),
    Text(String),
    BoxedInteger(i64),
    Float(f64),
    Rational(i64, i64),
    Complex(f64, f64),
    NumberLiteral(Arc<str>, f64),
    BignumLiteral(Arc<str>),
    RawDisplay(String),
    Commented(GcValue),
    Syntax(Arc<str>, GcValue),
    Iterator {
        sequence: GcValue,
        index: usize,
        names: Option<Vec<Arc<str>>>,
    },
    Dilambda {
        getter: GcValue,
        setter: GcValue,
    },
    Symbol(Arc<str>),
    Keyword(Arc<str>),
    Environment(Box<EnvironmentData>),
    LexicalFrame(Box<LexicalFrameData>),
    Builtin(BuiltinId),
    Macro(GcValue, bool),
    Closure {
        module: ModuleId,
        entry: u32,
        environment: GcValue,
    },
    InputPort(Box<(Vec<char>, usize)>),
    InputFunctionPort { callback: GcValue },
    OutputPort(String),
    OutputFunctionPort { callback: GcValue },
    HostProcedure(u16),
    HostHandle(u64),
}

impl GcObject {
    fn trace(&self, pending: &mut Vec<GcValue>) {
        match self {
            Self::Commented(value) | Self::Syntax(_, value) => pending.push(*value),
            Self::Iterator { sequence, .. } => pending.push(*sequence),
            Self::Dilambda { getter, setter } => {
                pending.push(*getter);
                pending.push(*setter)
            }
            Self::Pair { car, cdr } => {
                pending.push(*car);
                pending.push(*cdr);
            }
            Self::Vector(values) => pending.extend(values.iter().copied()),
            Self::MultiVector { values, .. } => pending.extend(values.iter().copied()),
            Self::MultiVectorView { base, .. } => pending.push(*base),
            Self::Values(values) => pending.extend(values.iter().copied()),
            Self::HashTable(table) => {
                pending.extend(table.iter().flat_map(|(key, value)| [*key, *value]));
                pending.extend(table.equivalence);
                pending.extend(table.key_checker);
                pending.extend(table.value_checker);
            }
            Self::Environment(data) => {
                pending.extend(data.parent);
                pending.extend(data.bindings.values().copied());
                pending.extend(data.history.iter().map(|(_, value)| *value));
            }
            Self::LexicalFrame(data) => {
                pending.extend(data.parent);
                pending.extend(data.slots.iter().copied());
                pending.extend(data.dynamic.values().copied());
                pending.extend(data.binding_setters.values().copied());
            }
            Self::Closure { environment, .. } => pending.push(*environment),
            Self::InputFunctionPort { callback } | Self::OutputFunctionPort { callback } => {
                pending.push(*callback)
            }
            Self::Macro(closure, ..) => pending.push(*closure),
            Self::ByteVector(_)
            | Self::FloatVector(_)
            | Self::IntVector(_)
            | Self::Text(_)
            | Self::BoxedInteger(_)
            | Self::Float(_)
            | Self::Rational(..)
            | Self::Complex(..)
            | Self::NumberLiteral(..)
            | Self::BignumLiteral(_)
            | Self::RawDisplay(_)
            | Self::InputPort(_)
            | Self::OutputPort(_)
            | Self::Symbol(_)
            | Self::Keyword(_)
            | Self::Builtin(_)
            | Self::HostProcedure(_)
            | Self::HostHandle(_) => {}
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RootMetaCar {
    builtin: BuiltinId,
    expected: GcValue,
}

#[derive(Debug)]
struct Slot {
    epoch: u32,
    marked: bool,
    request_generation: u32,
    age: u8,
    root_meta_car: Option<RootMetaCar>,
    object: Option<GcObject>,
}

impl Slot {
    fn empty() -> Self {
        Self {
            epoch: 1,
            marked: false,
            request_generation: 0,
            age: 0,
            root_meta_car: None,
            object: None,
        }
    }
}

#[derive(Default, Debug)]
struct RootRegistry {
    next: u64,
    roots: HashMap<u64, GcValue>,
}

#[derive(Debug)]
struct RootLeaseInner {
    id: u64,
    value: GcValue,
    registry: Weak<RefCell<RootRegistry>>,
}

impl Drop for RootLeaseInner {
    fn drop(&mut self) {
        if let Some(registry) = self.registry.upgrade() {
            registry.borrow_mut().roots.remove(&self.id);
        }
    }
}

/// A host-visible value is kept alive by an explicit root-table lease. Cloning a lease does
/// not duplicate the root entry; dropping the final clone removes it. A lease guarantees
/// memory-valid host observation and drop only. Its value cannot re-enter a later `run` until
/// an owner-approved continuity API also promotes all request-local semantic metadata.
#[derive(Clone, Debug)]
pub(crate) struct RootLease(Rc<RootLeaseInner>);

impl RootLease {
    pub(crate) fn value(&self) -> GcValue {
        self.0.value
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(crate) struct HeapStats {
    pub(crate) live: usize,
    pub(crate) capacity: usize,
    pub(crate) pages: usize,
    pub(crate) roots: usize,
    pub(crate) collections: u64,
    pub(crate) current_generation: u32,
}

#[derive(Debug, PartialEq, Eq)]
pub(crate) enum HeapError {
    QuotaExceeded { limit: usize },
    StaleHandle,
    WrongType,
    GenerationOverflow,
}

/// Interpreter-owned paged heap with explicit roots and request generations.
pub(crate) struct GcHeap {
    pages: Vec<Vec<Slot>>,
    free: Vec<u32>,
    registry: Rc<RefCell<RootRegistry>>,
    live: usize,
    quota: usize,
    collections: u64,
    current_generation: u32,
    next_generation: u32,
}

impl GcHeap {
    pub(crate) fn new(quota: usize) -> Self {
        Self {
            pages: Vec::new(),
            free: Vec::new(),
            registry: Rc::new(RefCell::new(RootRegistry::default())),
            live: 0,
            quota,
            collections: 0,
            current_generation: 0,
            next_generation: 1,
        }
    }

    pub(crate) fn stats(&self) -> HeapStats {
        HeapStats {
            live: self.live,
            capacity: self.pages.len() * PAGE_CELLS,
            pages: self.pages.len(),
            roots: self.registry.borrow().roots.len(),
            collections: self.collections,
            current_generation: self.current_generation,
        }
    }

    #[cfg(test)]
    fn root_meta_car_count(&self) -> usize {
        self.pages
            .iter()
            .flatten()
            .filter(|slot| slot.object.is_some() && slot.root_meta_car.is_some())
            .count()
    }

    pub(crate) fn root(&mut self, value: GcValue) -> Result<RootLease, HeapError> {
        if value.is_heap() {
            self.slot(value)?;
        }
        let mut registry = self.registry.borrow_mut();
        let id = registry.next;
        registry.next = registry
            .next
            .checked_add(1)
            .ok_or(HeapError::GenerationOverflow)?;
        registry.roots.insert(id, value);
        drop(registry);
        Ok(RootLease(Rc::new(RootLeaseInner {
            id,
            value,
            registry: Rc::downgrade(&self.registry),
        })))
    }

    pub(crate) fn begin_request_generation(&mut self) -> Result<u32, HeapError> {
        if self.current_generation != 0 {
            return Ok(self.current_generation);
        }
        let generation = self.next_generation;
        self.next_generation = self
            .next_generation
            .checked_add(1)
            .ok_or(HeapError::GenerationOverflow)?;
        self.current_generation = generation;
        Ok(generation)
    }

    /// Marks from all explicit roots, reclaims unreachable request objects, and promotes
    /// escaped survivors into the long-lived generation.
    pub(crate) fn finish_request_generation(&mut self) -> Result<usize, HeapError> {
        let generation = self.current_generation;
        if generation == 0 {
            return Ok(0);
        }
        self.mark_roots()?;
        let mut reclaimed = 0;
        for page in &mut self.pages {
            for slot in page {
                if slot.object.is_none() || slot.request_generation != generation {
                    slot.marked = false;
                    continue;
                }
                if slot.marked {
                    slot.marked = false;
                    slot.request_generation = 0;
                    slot.age = slot.age.saturating_add(1);
                } else {
                    slot.object = None;
                    slot.root_meta_car = None;
                    slot.epoch = next_epoch(slot.epoch);
                    reclaimed += 1;
                }
            }
        }
        if reclaimed != 0 {
            self.rebuild_free_list();
            self.live -= reclaimed;
        }
        self.current_generation = 0;
        self.collections += 1;
        Ok(reclaimed)
    }

    pub(crate) fn collect_full(&mut self) -> Result<usize, HeapError> {
        self.collect_full_with_roots(&[])
    }

    pub(crate) fn collect_full_with_roots(
        &mut self,
        temporary_roots: &[GcValue],
    ) -> Result<usize, HeapError> {
        self.mark_roots_with(temporary_roots)?;
        let mut reclaimed = 0;
        for page in &mut self.pages {
            for slot in page {
                if slot.object.is_none() {
                    slot.marked = false;
                    continue;
                }
                if slot.marked {
                    slot.marked = false;
                    slot.age = slot.age.saturating_add(1);
                } else {
                    slot.object = None;
                    slot.root_meta_car = None;
                    slot.epoch = next_epoch(slot.epoch);
                    reclaimed += 1;
                }
            }
        }
        if reclaimed != 0 {
            self.rebuild_free_list();
            self.live -= reclaimed;
        }
        self.collections += 1;
        Ok(reclaimed)
    }

    pub(crate) fn allocation_requires_collection(&self) -> bool {
        self.live >= self.quota
    }

    pub(crate) fn allocate(&mut self, object: GcObject) -> Result<GcValue, HeapError> {
        self.allocate_with_roots(object, &[])
    }

    pub(crate) fn allocate_with_roots(
        &mut self,
        object: GcObject,
        temporary_roots: &[GcValue],
    ) -> Result<GcValue, HeapError> {
        if self.live >= self.quota {
            self.collect_full_with_roots(temporary_roots)?;
            if self.live >= self.quota {
                return Err(HeapError::QuotaExceeded { limit: self.quota });
            }
        }
        if self.free.is_empty() {
            self.add_page()?;
        }
        let index = self.free.pop().expect("new page supplies free slots");
        let generation = self.current_generation;
        let epoch = {
            let slot = self
                .slot_index_mut(index)
                .expect("free-list index is valid");
            debug_assert!(slot.object.is_none());
            slot.object = Some(object);
            slot.request_generation = generation;
            slot.marked = false;
            slot.age = 0;
            slot.root_meta_car = None;
            slot.epoch
        };
        self.live += 1;
        Ok(GcValue::heap(index, epoch))
    }

    pub(crate) fn pair(&mut self, car: GcValue, cdr: GcValue) -> Result<GcValue, HeapError> {
        self.allocate(GcObject::Pair { car, cdr })
    }

    pub(crate) fn environment(
        &mut self,
        parent: Option<GcValue>,
        capacity: usize,
    ) -> Result<GcValue, HeapError> {
        self.allocate(GcObject::Environment(Box::new(EnvironmentData {
            parent,
            bindings: HashMap::with_capacity(capacity),
            order: Vec::with_capacity(capacity),
            history: Vec::new(),
        })))
    }

    pub(crate) fn environment_with_roots(
        &mut self,
        parent: Option<GcValue>,
        capacity: usize,
        temporary_roots: &[GcValue],
    ) -> Result<GcValue, HeapError> {
        self.allocate_with_roots(
            GcObject::Environment(Box::new(EnvironmentData {
                parent,
                bindings: HashMap::with_capacity(capacity),
                order: Vec::with_capacity(capacity),
                history: Vec::new(),
            })),
            temporary_roots,
        )
    }

    pub(crate) fn lexical_frame_with_roots(
        &mut self,
        parent: Option<GcValue>,
        slots: Vec<GcValue>,
        names: Arc<[Option<Arc<str>>]>,
        temporary_roots: &[GcValue],
    ) -> Result<GcValue, HeapError> {
        self.allocate_with_roots(
            GcObject::LexicalFrame(Box::new(LexicalFrameData {
                parent,
                slots,
                names,
                dynamic: HashMap::new(),
                binding_setters: HashMap::new(),
            })),
            temporary_roots,
        )
    }

    pub(crate) fn lexical_ancestor(&self, mut frame: GcValue, depth: u16) -> Result<GcValue, HeapError> {
        for _ in 0..depth {
            match self.object(frame)? {
                GcObject::LexicalFrame(data) if data.parent.is_some() => frame = data.parent.unwrap(),
                _ => return Err(HeapError::WrongType),
            }
        }
        Ok(frame)
    }

    pub(crate) fn lexical_get(
        &self,
        mut frame: GcValue,
        depth: u16,
        slot: u16,
    ) -> Result<GcValue, HeapError> {
        for _ in 0..depth {
            match self.object(frame)? {
                GcObject::LexicalFrame(data) if data.parent.is_some() => {
                    frame = data.parent.unwrap()
                }
                _ => return Err(HeapError::WrongType),
            }
        }
        match self.object(frame)? {
            GcObject::LexicalFrame(data) => data
                .slots
                .get(slot as usize)
                .copied()
                .ok_or(HeapError::WrongType),
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn lexical_set(
        &mut self,
        mut frame: GcValue,
        depth: u16,
        slot: u16,
        value: GcValue,
    ) -> Result<(), HeapError> {
        for _ in 0..depth {
            match self.object(frame)? {
                GcObject::LexicalFrame(data) if data.parent.is_some() => {
                    frame = data.parent.unwrap()
                }
                _ => return Err(HeapError::WrongType),
            }
        }
        match self.object_mut(frame)? {
            GcObject::LexicalFrame(data) => {
                let target = data
                    .slots
                    .get_mut(slot as usize)
                    .ok_or(HeapError::WrongType)?;
                *target = value;
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn lexical_binding_setter(
        &self,
        frame: GcValue,
        depth: u16,
        slot: u16,
    ) -> Result<Option<GcValue>, HeapError> {
        let owner = self.lexical_ancestor(frame, depth)?;
        match self.object(owner)? {
            GcObject::LexicalFrame(data) => Ok(data.binding_setters.get(&slot).copied()),
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn lexical_set_binding_setter(
        &mut self,
        frame: GcValue,
        depth: u16,
        slot: u16,
        setter: GcValue,
    ) -> Result<(), HeapError> {
        let owner = self.lexical_ancestor(frame, depth)?;
        match self.object_mut(owner)? {
            GcObject::LexicalFrame(data) => {
                data.binding_setters.insert(slot, setter);
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn lexical_update_slots(
        &mut self,
        frame: GcValue,
        arguments: &[GcValue],
        slot_count: usize,
        self_slot: Option<u16>,
        closure: GcValue,
    ) -> Result<(), HeapError> {
        match self.object_mut(frame)? {
            GcObject::LexicalFrame(data) => {
                data.slots.resize(slot_count, GcValue::UNDEFINED);
                data.slots.fill(GcValue::UNDEFINED);
                data.slots[..arguments.len()].copy_from_slice(arguments);
                if let Some(slot) = self_slot {
                    data.slots[slot as usize] = closure
                }
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn lexical_replace_slots(
        &mut self,
        frame: GcValue,
        mut values: Vec<GcValue>,
        slot_count: usize,
    ) -> Result<(), HeapError> {
        values.resize(slot_count, GcValue::UNDEFINED);
        match self.object_mut(frame)? {
            GcObject::LexicalFrame(data) => {
                data.slots = values;
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn closure(
        &mut self,
        module: ModuleId,
        entry: u32,
        environment: GcValue,
    ) -> Result<GcValue, HeapError> {
        self.closure_with_roots(module, entry, environment, &[environment])
    }

    pub(crate) fn closure_with_roots(
        &mut self,
        module: ModuleId,
        entry: u32,
        environment: GcValue,
        temporary_roots: &[GcValue],
    ) -> Result<GcValue, HeapError> {
        self.allocate_with_roots(
            GcObject::Closure {
                module,
                entry,
                environment,
            },
            temporary_roots,
        )
    }

    pub(crate) fn object(&self, value: GcValue) -> Result<&GcObject, HeapError> {
        self.slot(value)?
            .object
            .as_ref()
            .ok_or(HeapError::StaleHandle)
    }

    pub(crate) fn object_mut(&mut self, value: GcValue) -> Result<&mut GcObject, HeapError> {
        self.slot_mut(value)?
            .object
            .as_mut()
            .ok_or(HeapError::StaleHandle)
    }

    fn pair_root_meta_car(&self, pair: GcValue) -> Result<Option<RootMetaCar>, HeapError> {
        let slot = self.slot(pair)?;
        if !matches!(slot.object, Some(GcObject::Pair { .. })) {
            return Err(HeapError::WrongType);
        }
        Ok(slot.root_meta_car)
    }

    fn set_pair_root_meta_car(
        &mut self,
        pair: GcValue,
        builtin: Option<RootMetaCar>,
    ) -> Result<(), HeapError> {
        let slot = self.slot_mut(pair)?;
        if !matches!(slot.object, Some(GcObject::Pair { .. })) {
            return Err(HeapError::WrongType);
        }
        slot.root_meta_car = builtin;
        Ok(())
    }

    pub(crate) fn set_pair_car(&mut self, pair: GcValue, value: GcValue) -> Result<(), HeapError> {
        match self.object_mut(pair)? {
            GcObject::Pair { car, .. } => {
                *car = value;
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn set_pair_cdr(&mut self, pair: GcValue, value: GcValue) -> Result<(), HeapError> {
        match self.object_mut(pair)? {
            GcObject::Pair { cdr, .. } => {
                *cdr = value;
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn define(
        &mut self,
        environment: GcValue,
        name: &str,
        value: GcValue,
    ) -> Result<(), HeapError> {
        match self.object_mut(environment)? {
            GcObject::Environment(data) => {
                let name: Arc<str> = Arc::from(name);
                if !data.bindings.contains_key(&name) {
                    data.order.push(name.clone());
                }
                data.bindings.insert(name, value);
                Ok(())
            }
            GcObject::LexicalFrame(data) => {
                if let Some(index) = data
                    .names
                    .iter()
                    .position(|entry| entry.as_deref() == Some(name))
                {
                    data.slots[index] = value;
                } else {
                    data.dynamic.insert(Arc::from(name), value);
                }
                Ok(())
            }
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn environment_parent(
        &self,
        environment: GcValue,
    ) -> Result<Option<GcValue>, HeapError> {
        match self.object(environment)? {
            GcObject::Environment(data) => Ok(data.parent),
            GcObject::LexicalFrame(data) => Ok(data.parent),
            _ => Err(HeapError::WrongType),
        }
    }

    pub(crate) fn set_environment_parent(
        &mut self,
        environment: GcValue,
        parent: Option<GcValue>,
    ) -> Result<(), HeapError> {
        match self.object_mut(environment)? {
            GcObject::Environment(data) => data.parent = parent,
            GcObject::LexicalFrame(data) => data.parent = parent,
            _ => return Err(HeapError::WrongType),
        }
        Ok(())
    }

    pub(crate) fn set_binding(
        &mut self,
        mut environment: GcValue,
        name: &str,
        value: GcValue,
    ) -> Result<bool, HeapError> {
        loop {
            let parent = match self.object_mut(environment)? {
                GcObject::Environment(data) => {
                    if let Some(target) = data.bindings.get_mut(name) {
                        *target = value;
                        return Ok(true);
                    }
                    data.parent
                }
                GcObject::LexicalFrame(data) => {
                    if let Some(index) = data
                        .names
                        .iter()
                        .position(|entry| entry.as_deref() == Some(name))
                    {
                        data.slots[index] = value;
                        return Ok(true);
                    }
                    if let Some(target) = data.dynamic.get_mut(name) {
                        *target = value;
                        return Ok(true);
                    }
                    data.parent
                }
                _ => return Err(HeapError::WrongType),
            };
            if let Some(next) = parent {
                environment = next;
            } else {
                return Ok(false);
            }
        }
    }

    pub(crate) fn lookup(
        &self,
        mut environment: GcValue,
        name: &str,
    ) -> Result<Option<GcValue>, HeapError> {
        loop {
            let parent = match self.object(environment)? {
                GcObject::Environment(data) => {
                    if let Some(value) = data.bindings.get(name) {
                        return Ok(Some(*value));
                    }
                    data.parent
                }
                GcObject::LexicalFrame(data) => {
                    if let Some(index) = data
                        .names
                        .iter()
                        .position(|entry| entry.as_deref() == Some(name))
                    {
                        return Ok(Some(data.slots[index]));
                    }
                    if let Some(value) = data.dynamic.get(name) {
                        return Ok(Some(*value));
                    }
                    data.parent
                }
                _ => return Err(HeapError::WrongType),
            };
            if let Some(next) = parent {
                environment = next;
            } else {
                return Ok(None);
            }
        }
    }

    fn add_page(&mut self) -> Result<(), HeapError> {
        let start = self
            .pages
            .len()
            .checked_mul(PAGE_CELLS)
            .ok_or(HeapError::QuotaExceeded { limit: self.quota })?;
        if start > u32::MAX as usize - PAGE_CELLS {
            return Err(HeapError::QuotaExceeded { limit: self.quota });
        }
        let page = (0..PAGE_CELLS).map(|_| Slot::empty()).collect::<Vec<_>>();
        self.pages.push(page);
        self.free
            .extend((start..start + PAGE_CELLS).rev().map(|index| index as u32));
        Ok(())
    }

    fn mark_roots(&mut self) -> Result<(), HeapError> {
        self.mark_roots_with(&[])
    }

    fn mark_roots_with(&mut self, temporary_roots: &[GcValue]) -> Result<(), HeapError> {
        let mut pending = self
            .registry
            .borrow()
            .roots
            .values()
            .copied()
            .collect::<Vec<_>>();
        pending.extend_from_slice(temporary_roots);
        while let Some(value) = pending.pop() {
            let Some((index, epoch)) = value.heap_parts() else {
                continue;
            };
            let slot = self.slot_index_mut(index).ok_or(HeapError::StaleHandle)?;
            if slot.epoch != epoch || slot.object.is_none() {
                return Err(HeapError::StaleHandle);
            }
            if slot.marked {
                continue;
            }
            slot.marked = true;
            slot.object
                .as_ref()
                .expect("checked above")
                .trace(&mut pending);
            if let Some(root_meta_car) = slot.root_meta_car {
                pending.push(root_meta_car.expected);
            }
        }
        Ok(())
    }

    fn slot(&self, value: GcValue) -> Result<&Slot, HeapError> {
        let (index, epoch) = value.heap_parts().ok_or(HeapError::WrongType)?;
        let slot = self.slot_index(index).ok_or(HeapError::StaleHandle)?;
        if slot.epoch != epoch || slot.object.is_none() {
            return Err(HeapError::StaleHandle);
        }
        Ok(slot)
    }

    fn slot_mut(&mut self, value: GcValue) -> Result<&mut Slot, HeapError> {
        let (index, epoch) = value.heap_parts().ok_or(HeapError::WrongType)?;
        let slot = self.slot_index_mut(index).ok_or(HeapError::StaleHandle)?;
        if slot.epoch != epoch || slot.object.is_none() {
            return Err(HeapError::StaleHandle);
        }
        Ok(slot)
    }

    fn slot_index(&self, index: u32) -> Option<&Slot> {
        let index = index as usize;
        self.pages
            .get(index / PAGE_CELLS)
            .and_then(|page| page.get(index % PAGE_CELLS))
    }

    fn slot_index_mut(&mut self, index: u32) -> Option<&mut Slot> {
        let index = index as usize;
        self.pages
            .get_mut(index / PAGE_CELLS)
            .and_then(|page| page.get_mut(index % PAGE_CELLS))
    }

    fn rebuild_free_list(&mut self) {
        self.free.clear();
        for (page_index, page) in self.pages.iter().enumerate().rev() {
            for (slot_index, slot) in page.iter().enumerate().rev() {
                if slot.object.is_none() {
                    self.free
                        .push((page_index * PAGE_CELLS + slot_index) as u32);
                }
            }
        }
    }
}

fn next_epoch(epoch: u32) -> u32 {
    let next = (epoch + 1) & EPOCH_MASK;
    if next == 0 {
        1
    } else {
        next
    }
}

