                    let current = self.symbol_value("current")?;
                    let status = self.symbol_value(&self.gas_last_status.clone())?;
                    let used =
                        GcValue::fixnum(i64::try_from(self.gas_last_used).unwrap_or(i64::MAX))
                            .unwrap();
                    let remaining = self
                        .gas_remaining
                        .and_then(|remaining| i64::try_from(remaining).ok())
                        .and_then(GcValue::fixnum)
                        .unwrap_or(GcValue::FALSE);
                    let last = self.list_from_values(&[last, used, status])?;
                    let current = self.list_from_values(&[current, remaining])?;
                    self.list_from_values(&[last, current])?
