                    matches!(self.heap.object(arguments[0]), Ok(GcObject::Closure { .. }));
                let name: Arc<str> = if let Some(name) = self.syntax_name(arguments[0]) {
                    Arc::from(name)
                } else {
                    match self.heap.object(arguments[0]) {
                        Ok(GcObject::Builtin(BuiltinId::Car)) => Arc::from("car"),
                        Ok(GcObject::Builtin(BuiltinId::Add)) => Arc::from("+"),
                        Ok(GcObject::Builtin(BuiltinId::SyntaxIf)) => Arc::from("if"),
                        Ok(GcObject::Closure { .. }) => Arc::from(""),
                        _ => match self.value_name(arguments[0]) {
                            Ok(name) => name,
                            Err(_) => return Ok(self.values.push(GcValue::FALSE)),
                        },
                    }
                };
