                        let integer =
                            arguments[0]
                                .as_fixnum()
                                .ok_or_else(|| VmError::PairArgument {
                                    procedure: "integer->char",
                                    value: arguments[0],
                                    actual: self.value_kind_text(arguments[0]),
                                    expected: "an integer",
                                })?;
