                    let procedure = self.symbol_value("string-set!")?;
                    let supplied = self.list_from_values(&arguments)?;
                    let info = self.list_from_values(&[control, procedure, procedure, supplied])?;
                    let tag = self.symbol_value("wrong-number-of-args")?;
                    return Err(VmError::Scheme(SchemeCondition {
                        tag,
                        args: vec![info],
                    }));
