            | BuiltinId::FloatPredicate
            | BuiltinId::CharacterPredicate
            | BuiltinId::GensymPredicate
            | BuiltinId::EofPredicate
            | BuiltinId::BytePredicate
            | BuiltinId::PositivePredicate
            | BuiltinId::ProcedurePredicate
