    #[test]
    fn active_roots_cover_resumable_buffers_and_subvector_parents() {
        let mut vm = UnifiedVm::new(64, 1_000);
        let base = vm.heap.allocate(GcObject::Vector(vec![GcValue::TRUE])).unwrap();
        let view = vm.heap.allocate(GcObject::Vector(vec![GcValue::TRUE])).unwrap();
        vm.subvectors.insert(view, (base, 0));
        let merge_left = vm.heap.allocate(GcObject::Text("left".into())).unwrap();
        let merge_right = vm.heap.allocate(GcObject::Text("right".into())).unwrap();
        let merge_output = vm.heap.allocate(GcObject::Text("output".into())).unwrap();
        let seen = vm.heap.allocate(GcObject::Text("seen".into())).unwrap();
        let dead = vm.heap.allocate(GcObject::Text("dead".into())).unwrap();
        vm.pending_sorts.push(PendingSort {
            frame_depth: 1, stack_depth: 0, target: view, predicate: GcValue::TRUE,
            values: Vec::new(), mode: SortMode::Merge, outer: SortOuter::Build,
            awaiting: SortAwait::None, n: 0, k: 0, down_k: 0, down_j: 0, in_down: false,
            merge_ranges: Vec::new(), merge_index: 0, merge_left: vec![merge_left],
            merge_right: vec![merge_right], merge_output: vec![merge_output], merge_i: 0,
            merge_j: 0, network_stage: 0,
        });
        vm.pending_searches.push(PendingSearch {
            frame_depth: 1, stack_depth: 0, kind: SearchKind::Member,
            needle: GcValue::TRUE, cursor: GcValue::NIL, predicate: GcValue::TRUE,
            seen: HashSet::from([seen]), matched_value: GcValue::FALSE,
        });
        let roots = vm.all_active_roots_with(&[]);
        vm.heap.collect_full_with_roots(&roots).unwrap();
        for value in [base, view, merge_left, merge_right, merge_output, seen] {
            assert!(vm.heap.object(value).is_ok(), "missing request root {value:?}");
        }
        assert!(matches!(vm.heap.object(dead), Err(HeapError::StaleHandle)));
    }

    #[test]
    fn exceptional_unwind_consumes_pending_ownership_once() {
        let mut vm = UnifiedVm::new(64, 1_000);
        let previous_input = vm.heap.allocate(GcObject::InputPort(Box::new((Vec::new(), 0)))).unwrap();
        let previous_output = vm.heap.allocate(GcObject::OutputPort(String::new())).unwrap();
        let current_input = vm.heap.allocate(GcObject::InputPort(Box::new((Vec::new(), 0)))).unwrap();
        let current_output = vm.heap.allocate(GcObject::OutputPort(String::new())).unwrap();
        vm.current_input = Some(current_input);
        vm.current_output = Some(current_output);
        vm.pending_input_scopes.push(PendingInputScope { frame_depth: 3, stack_depth: 0, previous: Some(previous_input) });
        vm.pending_port_scopes.push(PendingPortScope { frame_depth: 3, stack_depth: 0, previous: Some(previous_output), output: None });
        vm.pending_invokes.push(PendingInvoke {
            frame_depth: 3, stack_depth: 0, tail: false, calling_environment: GcValue::NIL,
            procedure: GcValue::TRUE, raw_arguments: Vec::new(), evaluated: Vec::new(), next: 0,
            source_name: None, outer_context: None, syntax_result: false, call_source: None,
        });
        vm.pending_evals.push(PendingEval { frame_depth: 3, stack_depth: 0, initial: 100, outer_remaining: Some(200) });
        vm.gas_remaining = Some(60);
        vm.truncate_resumable_state(2, 0);
        assert!(vm.pending_invokes.is_empty());
        assert!(vm.pending_evals.is_empty());
        assert_eq!(vm.current_input, Some(previous_input));
        assert_eq!(vm.current_output, Some(previous_output));
        assert_eq!(vm.gas_last_used, 40);
        assert_eq!(vm.gas_last_status.as_ref(), "error");
        assert_eq!(vm.gas_remaining, Some(160));
        vm.truncate_resumable_state(2, 0);
        assert_eq!(vm.gas_remaining, Some(160), "cleanup must not replay ownership");
    }

    #[test]
    fn compact_handle_and_immutable_module_have_no_runtime_references() {
        assert_eq!(size_of::<GcValue>(), 8);
        eprintln!(
            "unified sizes: value={} slot={} object={}",
            size_of::<GcValue>(),
            size_of::<Slot>(),
            size_of::<GcObject>()
        );
        assert!(
            size_of::<Slot>() <= 96,
            "slot must remain within 2x the 48-byte C s7 cell"
        );
        assert!(GcValue::fixnum((1_i64 << 60) - 1).is_some());
        assert!(GcValue::fixnum(1_i64 << 60).is_none());
        assert_eq!(GcValue::fixnum(-17).unwrap().as_fixnum(), Some(-17));
        assert_eq!(GcValue::character('λ').as_character(), Some('λ'));
        let module = ImmutableModule {
            id: ModuleId(7),
            code: Arc::from([UnifiedInstruction::Constant(0), UnifiedInstruction::Return]),
            functions: Arc::from([UnifiedFunction {
                entry: 0,
                arity: 0,
                local_count: 0,
                reusable_tail_frame: false,
                self_slot: None,
                star: None,
                local_names: Arc::from([]),
                rest_slot: None,
                curlet_parent: false,
                source: Arc::from(""),
            }]),
            constants: Arc::from([FrozenConstant::Fixnum(42)]),
            tail_self_binary: Arc::from([]),
            semantic_abi: UNIFIED_SEMANTIC_ABI,
        };
        assert_eq!(module.code.len(), 2);
    }

    #[test]
    fn tracing_preserves_rooted_cycles_and_reclaims_them_after_drop() {
        let mut heap = GcHeap::new(64);
        let pair = heap.pair(GcValue::NIL, GcValue::NIL).unwrap();
        heap.set_pair_car(pair, pair).unwrap();
        let root = heap.root(pair).unwrap();
        assert_eq!(heap.collect_full().unwrap(), 0);
        assert!(matches!(
            heap.object(root.value()),
            Ok(GcObject::Pair { .. })
        ));
        drop(root);
        assert_eq!(heap.collect_full().unwrap(), 1);
        assert!(matches!(heap.object(pair), Err(HeapError::StaleHandle)));
    }

    #[test]
    fn closure_environment_cycles_are_collected_without_reference_counting() {
        let mut heap = GcHeap::new(64);
        let environment = heap.environment(None, 1).unwrap();
        let closure = heap.closure(ModuleId(1), 0, environment).unwrap();
        heap.define(environment, "f", closure).unwrap();
        let root = heap.root(closure).unwrap();
        heap.collect_full().unwrap();
        assert_eq!(heap.lookup(environment, "f").unwrap(), Some(closure));
        drop(root);
        assert_eq!(heap.collect_full().unwrap(), 2);
        assert_eq!(heap.stats().live, 0);
    }

    #[test]
    fn builtin_metadata_registry_is_complete_and_pinned() {
        use crate::builtin_metadata::{metadata, ENTRIES, REGISTRY_VERSION, SOURCE_PATH, SOURCE_SHA256};
        assert_eq!(REGISTRY_VERSION, 1);
        assert_eq!(SOURCE_PATH, "journal/external/s7/s7.c");
        assert_eq!(SOURCE_SHA256, "91bb94c6b5604b8081a6f49c221f923c586c6d76ad717554592fe8d9fd4ce525");
        assert_eq!(ENTRIES.len(), APPROVED_ROOT_SYNTAX.len() + APPROVED_ROOT_BUILTINS.len());
        let mut names = HashSet::new();
        for name in APPROVED_ROOT_SYNTAX.iter().chain(APPROVED_ROOT_BUILTINS) {
            assert!(names.insert(*name), "duplicate approved metadata name: {name}");
            assert!(metadata(name).is_some(), "missing approved metadata entry: {name}");
        }
        let source = include_str!("../../journal/external/s7/s7.c");
        for entry in ENTRIES.iter().filter(|entry| entry.documentation.is_some()) {
            let provenance = format!("#define {}", entry.source_macro.unwrap());
            assert!(source.contains(&provenance), "missing provenance for {}", entry.name);
            assert!(entry.source_line.is_some());
        }
        let format = metadata("format").unwrap();
        assert_eq!(format.source_macro, Some("H_format"));
        assert!(format.documentation.unwrap().starts_with("(format out str . args)"));
        assert!(format.documentation.unwrap().contains("~P inserts \"s\""));
        assert_eq!((format.minimum_arity, format.maximum_arity), (2, 536_870_912));
        assert!(format.signature.is_some());
        let eval = metadata("eval").unwrap();
        assert_eq!((eval.minimum_arity, eval.maximum_arity), (1, 2));
        assert!(eval.signature.is_some());
        assert_eq!((metadata("+").unwrap().minimum_arity, metadata("+").unwrap().maximum_arity), (0, 536_870_912));
        assert_eq!(metadata("*s7*").unwrap().documentation, None);
    }

    #[test]
    fn cyclic_syntax_and_environment_graphs_are_bounded_and_reconstructive() {
        assert_eq!(
            run_source_output("(let ((x '(car (list 1 2 3)))) (set! (x 0) x) (catch #t (lambda () (eval x)) (lambda args args)))").unwrap(),
            "(syntax-error (\"attempt to evaluate a circular list: ~A\" #1=(#1# (list 1 2 3))))"
        );
        assert_eq!(
            run_source_output("(let ((hi 3)) (let ((e (curlet))) (set! hi (curlet)) (object->string e)))").unwrap(),
            "\"#1=(inlet 'hi #2=(inlet 'e #1#))\""
        );
        assert_eq!(
            run_source_output("(let ((e (inlet)) (p (cons #f '()))) (set-car! p e) (varlet e 'p p) (object->string e))").unwrap(),
            "\"#1=(inlet 'p (#1#))\""
        );
        assert_eq!(
            run_source_output("(let ((a (inlet 'x 1)) (b (inlet 'y 2))) (set! (outlet a) b) (set! (outlet b) a))").unwrap_or_else(|error| error),
            "(error (cyclic-let (\"set! (outlet ~A) creates a cyclic let chain\" (inlet 'y 2))))"
        );
        assert_eq!(
            run_source_output("(let ((x '(1 2))) (set-cdr! (cdr x) x) (eq? (eval (list 'quote x)) x))").unwrap(),
            "#t"
        );
        assert_eq!(
            run_source_output("(let ((x '(1 2))) (let ((y (eval (list 'quote x)))) (set-car! y 9) (list x y)))").unwrap(),
            "((9 2) (9 2))"
        );
        let quoted_source = "(let ((x '(1 2))) (set-cdr! (cdr x) x) (eq? (eval (list 'quote x)) x))";
        let quoted_module = UnifiedCompiler::compile(ModuleId(0), quoted_source).unwrap();
        let mut quoted_completed = false;
        for quota in 96..=512 {
            let mut vm = UnifiedVm::new(quota, 2_000_000);
            vm.install_module(quoted_module.clone());
            match vm.run(ModuleId(0), FunctionId(0), &[]) {
                Ok(result) => {
                    assert_eq!(vm.format_value(result.value()).unwrap(), "#t");
                    assert!(vm.heap.stats().collections > 0);
                    quoted_completed = true;
                    break;
                }
                Err(VmError::Heap(HeapError::QuotaExceeded { .. })) => {}
                Err(error) => panic!("quoted quota {quota}: {error:?}"),
            }
        }
        assert!(quoted_completed, "quoted cyclic literal never completed under forced collection");
        let source = "(let ((x '(car (list 1 2 3))) (n 0)) (set! (x 0) x) (list (catch #t (lambda () (set! n (+ n 1)) (eval x)) (lambda args 'error)) n))";
        let module = UnifiedCompiler::compile(ModuleId(0), source).unwrap();
        let mut completed = false;
        for quota in 96..=512 {
            let mut vm = UnifiedVm::new(quota, 2_000_000);
            vm.install_module(module.clone());
            match vm.run(ModuleId(0), FunctionId(0), &[]) {
                Ok(result) => {
                    assert_eq!(vm.format_value(result.value()).unwrap(), "(error 1)");
                    assert!(vm.heap.stats().collections > 0);
                    completed = true;
                    break;
                }
                Err(VmError::Heap(HeapError::QuotaExceeded { .. })) => {}
                Err(error) => panic!("quota {quota}: {error:?}"),
            }
        }
        assert!(completed, "cyclic eval never completed under forced collection");
    }

    #[test]
    fn request_generation_reclaims_transients_and_promotes_escaped_values() {
        let mut heap = GcHeap::new(128);
        heap.begin_request_generation().unwrap();
        let transient = heap
            .pair(GcValue::fixnum(1).unwrap(), GcValue::NIL)
            .unwrap();
        let escaped = heap
            .pair(GcValue::fixnum(2).unwrap(), GcValue::NIL)
            .unwrap();
        let root = heap.root(escaped).unwrap();
        assert_eq!(heap.finish_request_generation().unwrap(), 1);
        assert!(matches!(
            heap.object(transient),
            Err(HeapError::StaleHandle)
        ));
        assert!(heap.object(escaped).is_ok());
        assert_eq!(heap.stats().current_generation, 0);
        drop(root);
        assert_eq!(heap.collect_full().unwrap(), 1);
    }

    #[test]
    fn stale_handles_cannot_alias_reused_slots() {
        let mut heap = GcHeap::new(4);
        let old = heap.pair(GcValue::NIL, GcValue::NIL).unwrap();
        heap.collect_full().unwrap();
        let replacement = heap.pair(GcValue::TRUE, GcValue::NIL).unwrap();
        assert_ne!(old, replacement);
        assert!(matches!(heap.object(old), Err(HeapError::StaleHandle)));
        assert!(heap.object(replacement).is_ok());
    }

    #[test]
    fn quotas_fail_closed_after_collection() {
        let mut heap = GcHeap::new(2);
        let first = heap.pair(GcValue::NIL, GcValue::NIL).unwrap();
        let second = heap.pair(first, GcValue::NIL).unwrap();
        let _first = heap.root(first).unwrap();
        let _second = heap.root(second).unwrap();
        assert_eq!(
            heap.pair(GcValue::NIL, GcValue::NIL),
            Err(HeapError::QuotaExceeded { limit: 2 })
        );
    }

