    #[test]
    fn function_ports_resume_callbacks_once_under_quota_pressure() {
        let cases = [
            (ModuleId(16), "(let ((seen '()) (p #f)) (set! p (open-output-function (lambda (byte) (set! seen (cons byte seen)) (vector byte)))) (list (write-string \"abc\" p) (reverse seen)))", "(\"abc\" (97 98 99))"),
            (ModuleId(17), "(let ((n 0) (p #f)) (set! p (open-input-function (lambda (choice) (set! n (+ n 1)) (vector choice) #\\a))) (list (read-char p) n))", "(#\\a 1)"),
            (ModuleId(18), "(let ((seen '()) (p #f)) (set! p (open-output-function (lambda (byte) (set! seen (cons byte seen)) (if (= byte 98) (error 'boom \"bad\") #t)))) (list (catch #t (lambda () (write-string \"abc\" p)) (lambda args args)) (reverse seen)))", "((boom (\"bad\")) (97 98))"),
            (ModuleId(19), "(let ((seen '()) (inner #f) (outer #f)) (set! inner (open-output-function (lambda (byte) (set! seen (cons byte seen))))) (set! outer (open-output-function (lambda (byte) (write-char #\\z inner) (set! seen (cons byte seen))))) (write-char #\\a outer) (reverse seen))", "(122 97)"),
            (ModuleId(20), "(catch #t (lambda () (read-char (open-input-function (lambda (choice) (string #\\a))))) (lambda args args))", "(wrong-type-arg (\"input-function-port read-char returned: ~S\" \"a\"))"),
        ];
        for (module_id, source, expected) in cases {
            let module = UnifiedCompiler::compile(module_id, source).unwrap();
            let mut succeeded = false;
            for quota in (20..=500).step_by(8) {
                let mut vm = UnifiedVm::new(quota, 2_000_000);
                vm.force_function_port_return_collection = true;
                vm.install_module(module.clone());
                match vm.run(module_id, FunctionId(0), &[]) {
                    Ok(result) => {
                        assert_eq!(vm.format_value(result.value()).unwrap(), expected, "quota {quota}");
                        succeeded = true;
                    }
                    Err(VmError::Heap(HeapError::QuotaExceeded { .. })) => {}
                    Err(error) => panic!("quota {quota}: {error:?}"),
                }
            }
            assert!(succeeded, "no successful quota for {source}");
        }
    }

