    #[test]
    fn typed_hash_tables_trace_retained_checkers() {
        let mut heap = GcHeap::new(8);
        let key_checker = heap
            .allocate(GcObject::Builtin(BuiltinId::SymbolPredicate))
            .unwrap();
        let value_checker = heap
            .allocate(GcObject::Builtin(BuiltinId::IntegerPredicate))
            .unwrap();
        let table = heap
            .allocate_with_roots(
                GcObject::HashTable(Box::new(HashTableData {
                    key_checker: Some(key_checker),
                    value_checker: Some(value_checker),
                    key_checker_name: Some(Arc::from("symbol?")),
                    value_checker_name: Some(Arc::from("integer?")),
                    ..HashTableData::default()
                })),
                &[key_checker, value_checker],
            )
            .unwrap();
        let _table = heap.root(table).unwrap();
        heap.collect_full().unwrap();
        assert!(heap.object(key_checker).is_ok());
        assert!(heap.object(value_checker).is_ok());
    }

